use std::io

fn is_int(tok: string) -> bool {
    let mut digits = 0
    let mut bad = false
    let mut idx = 0
    for c in tok.chars() {
        if c >= '0' && c <= '9' {
            digits += 1
        } else if !(idx == 0 && c == '-') {
            bad = true
        }
        idx += 1
    }
    digits > 0 && !bad
}

fn eval(line: string) -> string {
    let mut stack: Vec<int> = []
    for tok in line.split_whitespace() {
        if tok == "+" || tok == "-" || tok == "*" || tok == "/" {
            if stack.len() < 2 {
                return "error: underflow"
            }
            let b = stack.pop() ?? 0
            let a = stack.pop() ?? 0
            if tok == "+" {
                stack.push(a + b)
            } else if tok == "-" {
                stack.push(a - b)
            } else if tok == "*" {
                stack.push(a * b)
            } else {
                if b == 0 {
                    return "error: divzero"
                }
                stack.push(a / b)
            }
        } else if is_int(tok) {
            stack.push(tok.parse::<int>() ?? 0)
        } else {
            return "error: token"
        }
    }
    if stack.len() != 1 {
        return "error: leftover"
    }
    "${stack[0]}"
}

fn main() {
    let text = io::read_to_string(io::stdin()) ?? ""
    for line in text.lines() {
        if line.trim().len() == 0 {
            continue
        }
        println(eval(line))
    }
}

